<?php
require_once __DIR__.'/../includes/permissions.php'; require_api_login(); require_permission('export_data');
$type=$_GET['type']??'feedback';header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="'.$type.'-'.date('Ymd-His').'.csv"');$out=fopen('php://output','w');
if($type==='feedback'){fputcsv($out,['ID','Department','Category','Feedback','Sentiment','Status','Created']);$rows=db()->query('SELECT f.id,d.name department,c.name category,f.feedback_text,f.sentiment,f.status,f.created_at FROM anonymous_feedback f JOIN departments d ON d.id=f.department_id LEFT JOIN feedback_categories c ON c.id=f.category_id ORDER BY f.created_at DESC');foreach($rows as $r)fputcsv($out,$r);}else{fputcsv($out,['Survey','Response ID','Submitted']);$rows=db()->query('SELECT s.title,r.id,r.submitted_at FROM survey_responses r JOIN surveys s ON s.id=r.survey_id WHERE r.submitted_at IS NOT NULL ORDER BY r.submitted_at DESC');foreach($rows as $r)fputcsv($out,$r);}fclose($out);exit;
